require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/schema.php';$schema=dental_schema($pdo);$labId=$schema->labId();$serviceCol=$schema->serviceId();$serviceId=$serviceCol;$serviceName=$schema->serviceName();$imageId=$schema->imageId();$imagePath=$schema->imagePath();$published=$schema->status('valide');
$q=trim((string)($_GET['q']??''));$city=trim((string)($_GET['ville']??''));$serviceFilter=filter_var($_GET['service']??'',FILTER_VALIDATE_INT);if(!$serviceFilter||$serviceFilter<1)$serviceFilter=null;$page=max(1,(int)($_GET['page']??1));$perPage=9;
$cities=$pdo->prepare('SELECT DISTINCT ville FROM laboratoire WHERE statut=? AND ville<>\'\' ORDER BY ville');$cities->execute([$published]);$cities=$cities->fetchAll(PDO::FETCH_COLUMN);
$sql="SELECT DISTINCT s.`$serviceCol` id,s.`$serviceName` nom FROM service s JOIN laboratoire_service ls ON ls.service_id=s.`$serviceCol` JOIN laboratoire l ON l.`$labId`=ls.laboratoire_id WHERE l.statut=? ORDER BY s.`$serviceName`";$stmt=$pdo->prepare($sql);$stmt->execute([$published]);$services=$stmt->fetchAll();
$where=['l.statut=?'];$params=[$published];if($q!==''){$where[]='(l.nom_laboratoire LIKE ? OR l.ville LIKE ? OR l.adresse LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term);}if($city!==''){$where[]='l.ville=?';$params[]=$city;}if($serviceFilter){$where[]='EXISTS(SELECT 1 FROM laboratoire_service sf WHERE sf.laboratoire_id=l.`'.$labId.'` AND sf.service_id=?)';$params[]=$serviceFilter;}$whereSql=implode(' AND ',$where);
$count=$pdo->prepare('SELECT COUNT(*) FROM laboratoire l WHERE '.$whereSql);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$sql="SELECT l.`$labId` id,l.nom_laboratoire,l.ville,l.adresse,l.description,(SELECT i.`$imagePath` FROM image_laboratoire i WHERE i.laboratoire_id=l.`$labId` ORDER BY i.`$imageId` LIMIT 1) photo,GROUP_CONCAT(DISTINCT s.`$serviceName` ORDER BY s.`$serviceName` SEPARATOR '|') services FROM laboratoire l LEFT JOIN laboratoire_service ls ON ls.laboratoire_id=l.`$labId` LEFT JOIN service s ON s.`$serviceCol`=ls.service_id WHERE $whereSql GROUP BY l.`$labId` ORDER BY l.`$labId` DESC LIMIT $perPage OFFSET $offset";$stmt=$pdo->prepare($sql);$stmt->execute($params);$labs=$stmt->fetchAll();$labPhotos=[];if($labs){$ids=array_column($labs,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$photoStmt=$pdo->prepare("SELECT laboratoire_id, `$imagePath` photo FROM image_laboratoire WHERE laboratoire_id IN ($marks) ORDER BY `$imageId`");$photoStmt->execute($ids);foreach($photoStmt->fetchAll() as $photoRow)$labPhotos[$photoRow['laboratoire_id']][]=$photoRow['photo'];}$queryParams=[];if($q!=='')$queryParams['q']=$q;if($city!=='')$queryParams['ville']=$city;if($serviceFilter)$queryParams['service']=$serviceFilter;$pageUrl=static fn(int $p):string=>'laboratoires.php?'.http_build_query($queryParams+['page'=>$p]);
$pageTitle='Annuaire des laboratoires — DentalLink';$pageDescription='Recherchez des laboratoires de prothèses dentaires au Maroc par ville et spécialité.';$pageStyles=['assets/css/public.css'];$loadInterFont=true;require __DIR__.'/includes/header.php';require_once __DIR__.'/includes/public-nav.php';
?><main><section class="page-hero"><div class="container"><div class="breadcrumb"><a href="index.php">Accueil</a>　›　Annuaire</div><h1>Laboratoires dentaires</h1><p>Trouvez un partenaire professionnel selon sa ville et ses spécialités.</p></div></section><section class="directory"><div class="container"><form class="filter-panel" action="laboratoires.php" method="get"><input type="search" name="q" value="<?=e($q)?>" placeholder="Nom, ville ou adresse" aria-label="Rechercher par nom"><select name="ville" aria-label="Filtrer par ville"><option value="">Toutes les villes</option><?php foreach($cities as $c):?><option value="<?=e($c)?>" <?=$city===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><select name="service" aria-label="Filtrer par service"><option value="">Tous les services</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=$serviceId===(int)$s['id']?'selected':''?>><?=e($s['nom'])?></option><?php endforeach;?></select><button class="btn btn-primary" type="submit">Filtrer</button><a class="btn btn-soft" href="laboratoires.php">Réinitialiser</a></form><div class="result-row"><span><?=number_format($total,0,',',' ')?> laboratoire<?=($total>1?'s':'')?> trouvé<?=($total>1?'s':'')?></span><?php if($total):?><span>Page <?=$page?> sur <?=$pages?></span><?php endif;?></div><?php if($labs):?><div class="cards"><?php foreach($labs as $lab):$photos=$labPhotos[$lab['id']]??[];$photosJson=e(json_encode($photos,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP));$directoryAddress=trim((string)($lab['adresse']??''));$directoryHost=strtolower((string)parse_url($directoryAddress,PHP_URL_HOST));$directoryIsMaps=filter_var($directoryAddress,FILTER_VALIDATE_URL)!==false&&(in_array($directoryHost,['maps.app.goo.gl','goo.gl','maps.google.com'],true)||($directoryHost==='google.com'&&str_starts_with((string)parse_url($directoryAddress,PHP_URL_PATH),'/maps')));?><article class="lab-card"><div class="directory-gallery"><img class="lab-photo directory-card-photo" src="<?=e(($photos[0]??'')?:($lab['photo']?:'assets/images/lab-placeholder.svg'))?>" data-photos="<?=$photosJson?>" alt="Laboratoire <?=e($lab['nom_laboratoire'])?>"><?php if(count($photos)>0):?><span class="directory-photo-count"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="8.5" cy="10" r="1.5"/><path d="m21 15-5-5L5 19"/></svg><?=count($photos)?> photos</span><?php endif;?><span class="directory-verified"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m8 12 2.5 2.5L16 9"/></svg>Laboratoire validé</span><?php if(count($photos)>1):?><button class="directory-gallery-arrow directory-gallery-prev" type="button" data-gallery-prev aria-label="Photo précédente"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg></button><button class="directory-gallery-arrow directory-gallery-next" type="button" data-gallery-next aria-label="Photo suivante"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button><div class="directory-gallery-dots" role="group" aria-label="Photos du laboratoire"><?php foreach($photos as $photoIndex=>$galleryPhoto):?><button type="button" class="directory-gallery-dot <?=$photoIndex===0?'active':''?>" data-gallery-index="<?=$photoIndex?>" aria-label="Afficher la photo <?=$photoIndex+1?>"></button><?php endforeach;?></div><?php endif;?></div><div class="lab-content"><h2 class="lab-title"><?=e($lab['nom_laboratoire'])?></h2><div class="lab-location"><svg class="directory-location-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg><?=e($lab['ville'])?><?php if(!$directoryIsMaps&&$directoryAddress!==''):?> · <?=e($directoryAddress)?><?php endif;?></div><p class="lab-description"><?=e(text_excerpt((string)($lab['description']??''),130))?></p><h3 class="directory-services-title"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7.2 3.5c1.8 0 2.6 1 4.8 1s3-1 4.8-1c2.5 0 4.2 2 4.2 5 0 4.1-2.1 6.3-3.1 9.7-.5 1.8-1.1 3.3-2.2 3.3-1.5 0-1.6-5.2-3.7-5.2s-2.2 5.2-3.7 5.2c-1.1 0-1.7-1.5-2.2-3.3C5.1 14.8 3 12.6 3 8.5c0-3 1.7-5 4.2-5Z"/></svg>Services proposés</h3><div class="chips"><?php foreach(array_slice(explode('|',(string)$lab['services']),0,4) as $svc):?><?php if($svc!==''):?><span class="chip"><svg class="directory-tooth-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M7.2 3.5c1.8 0 2.6 1 4.8 1s3-1 4.8-1c2.5 0 4.2 2 4.2 5 0 4.1-2.1 6.3-3.1 9.7-.5 1.8-1.1 3.3-2.2 3.3-1.5 0-1.6-5.2-3.7-5.2s-2.2 5.2-3.7 5.2c-1.1 0-1.7-1.5-2.2-3.3C5.1 14.8 3 12.6 3 8.5c0-3 1.7-5 4.2-5Z"/></svg><?=e($svc)?></span><?php endif;?><?php endforeach;?></div><a class="card-link" href="laboratoire-details.php?id=<?=$lab['id']?>">Voir le laboratoire →</a></div></article><?php endforeach;?></div><?php if($pages>1):?><nav class="pagination" aria-label="Pagination des laboratoires"><?php if($page>1):?><a class="page-link" href="<?=e($pageUrl($page-1))?>" aria-label="Page précédente">‹</a><?php endif;?><?php for($n=max(1,$page-2);$n<=min($pages,$page+2);$n++):?><a class="page-link <?=$n===$page?'active':''?>" href="<?=e($pageUrl($n))?>" <?=$n===$page?'aria-current="page"':''?>><?=$n?></a><?php endfor;?><?php if($page<$pages):?><a class="page-link" href="<?=e($pageUrl($page+1))?>" aria-label="Page suivante">›</a><?php endif;?></nav><?php endif;?><?php else:?><div class="empty"><span class="service-icon">⌕</span><h2>Aucun laboratoire trouvé</h2><p>Essayez d’autres critères ou réinitialisez les filtres.</p><a class="btn btn-primary" href="laboratoires.php">Voir tous les laboratoires</a></div><?php endif;?></div></section></main><?php require_once __DIR__.'/includes/public-footer.php'; ?></body></html>
